t.script:
(function(){
  var KK = document.getElementById('hh-k').getAttribute('data-k');
  function toDec(v){ if(!v){ return 0; } var p=v.split(':'); return parseInt(p[0]) + parseInt(p[1]||0)/60; }
  function totOf(card){
    var t = 0;
    for(var i=0;i<7;i++){
      var g = get(card, i);
      t += Math.max(g[1]-g[0], 0) + Math.max(g[3]-g[2], 0);
    }
    return t;
  }
  function get(card, d){
    var out = [0,0,0,0];
    card.querySelectorAll('input[data-d="'+d+'"]').forEach(function(inp){ out[parseInt(inp.getAttribute('data-f'))] = toDec(inp.value); });
    return out;
  }
  function refreshTot(card){
    var el = card.querySelector('[data-role="tot"]');
    if(el){ el.textContent = 'Total : ' + (Math.round(totOf(card)*100)/100) + ' h/sem'; }
  }
  document.addEventListener('input', function(e){
    if(e.target.matches('.hh-form input')){ refreshTot(e.target.closest('.hh-emp')); }
  });
  document.addEventListener('click', function(e){
    var ed = e.target.closest('.hh-edit');
    if(ed){
      var f = ed.closest('.hh-emp').querySelector('.hh-form');
      f.style.display = (f.style.display === 'block') ? 'none' : 'block';
      refreshTot(ed.closest('.hh-emp'));
      return;
    }
    var b = e.target.closest('.hh-b[data-act]');
    if(!b){ return; }
    var card = b.closest('.hh-emp');
    var act = b.getAttribute('data-act');
    if(act === 'lundi'){
      for(var f2=0; f2<4; f2++){
        var src = card.querySelector('input[data-d="0"][data-f="'+f2+'"]').value;
        for(var d=1; d<=4; d++){ card.querySelector('input[data-d="'+d+'"][data-f="'+f2+'"]').value = src; }
      }
      refreshTot(card);
      return;
    }
    if(act === 'clear'){
      card.querySelectorAll('.hh-form input').forEach(function(i){ i.value=''; });
      refreshTot(card);
      return;
    }
    if(act === 'save'){
      var hor = [];
      for(var d2=0; d2<7; d2++){ hor.push(get(card, d2)); }
      if(totOf(card) <= 0){ alert('Renseignez au moins une plage horaire.'); return; }
      b.disabled = true;
      fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[2021]],kwargs:{context:{active_model:'hr.employee',emp_id:parseInt(card.getAttribute('data-emp')),horaires:hor,hj_k:KK}}}})
      }).then(function(r){return r.json();}).then(function(d){
        b.disabled = false;
        if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
        alert('✓ Horaire enregistré (' + ((d.result||{}).total||0).toFixed(2) + ' h/sem) pour ' + card.getAttribute('data-name'));
        location.reload();
      }).catch(function(){ b.disabled = false; alert('Échec réseau'); });
    }
  });
})();
